      const ln=dr(el('path',{d:`M${f2(o.x)},${f2(o.y)} L${f2(ex)},${f2(ty)} L${f2(lx)},${f2(ty)}`,fill:'none',stroke:col(lineColor||o.color||color||'a2'),'stroke-width':f2(2.5*SU),'stroke-opacity':.9},g));
