function rk4(f,y,t,dt){const k1=f(t,y),k2=f(t+dt/2,y.map((v,i)=>v+k1[i]*dt/2)),k3=f(t+dt/2,y.map((v,i)=>v+k2[i]*dt/2)),k4=f(t+dt,y.map((v,i)=>v+k3[i]*dt));return y.map((v,i)=>v+dt/6*(k1[i]+2*k2[i]+2*k3[i]+k4[i]))}
