    const jd=lastDone>=1?lastDone:-1;const ligOn=jd>=1&&st2[jd]&&(st2[jd].left<=st2[jd].bound+.5);lig.setAttribute('opacity',ligOn?.95:0);if(ligOn){lig.setAttribute('cx',f2(P[jd-1]));lig.setAttribute('cy',f2(yG))}
