    A.parent=[f2((F+X1)/2)*1,410];A.helicase=[F-10,410-40];A.template=[X0+140,yT];A.leading=[X0+140,yL];A.polymerase=[Lend-40,yL-60];A.lagging=[X0+60,yG];
