  const ball=(G,x,y,r=26)=>el('circle',{cx:x,cy:y,r,fill:vol(C),stroke:dark(C),'stroke-width':2},G);const rod=(G,x,y,a=0,l=90)=>el('rect',{x:x-l/2,y:y-20,width:l,height:40,rx:20,transform:`rotate(${a} ${x} ${y})`,fill:vol(C),stroke:dark(C),'stroke-width':2},G);
  L.forEach((k,i)=>{const x=(i%cols+.5)*cw,y=Math.floor(i/cols)*ch+ch*.42,G=el('g',{},g);el('rect',{x:x-cw/2+10,y:y-ch*.42+6,width:cw-20,height:ch-12,rx:20,fill:TH.panel,stroke:TH.faint,'stroke-width':2},G);txt(G,T(BSN[k]),x,y+ch*.48,{size:26,color:'ink'});
    if(k==='cocci')[[-70,-10],[20,-30],[70,30],[-20,40]].forEach(([dx,dy])=>ball(G,x+dx,y+dy));if(k==='diplococci')[[-80,0],[60,-20]].forEach(([dx,dy])=>{ball(G,x+dx-24,y+dy);ball(G,x+dx+24,y+dy)});
    if(k==='streptococci')for(let j=0;j<7;j++)ball(G,x-150+j*50,y+Math.sin(j*.9)*24,24);if(k==='staphylococci')[[0,0],[48,0],[-48,0],[24,-40],[-24,-40],[24,40],[-24,40],[72,-40],[-72,40],[0,-80]].forEach(([dx,dy])=>ball(G,x+dx,y+dy-10,24));
    if(k==='bacilli')[[-90,-20,10],[60,10,-15],[-10,50,30]].forEach(([dx,dy,a])=>rod(G,x+dx,y+dy,a));if(k==='streptobacilli')for(let j=0;j<4;j++)rod(G,x-150+j*100,y,0,94);
    if(k==='vibrio')[[-80,0],[80,-10]].forEach(([dx,dy])=>{el('path',{d:`M${x+dx-50},${y+dy+10} Q${x+dx},${y+dy-50} ${x+dx+50},${y+dy+10}`,fill:'none',stroke:dark(C),'stroke-width':40,'stroke-linecap':'round'},G);el('path',{d:`M${x+dx-50},${y+dy+10} Q${x+dx},${y+dy-50} ${x+dx+50},${y+dy+10}`,fill:'none',stroke:C,'stroke-width':34,'stroke-linecap':'round'},G);
      const fl=el('path',{fill:'none',stroke:dark(C),'stroke-width':3},G);up.push(lt=>fl.setAttribute('d',wavy(x+dx+52,y+dy+12,x+dx+130,y+dy+40,8+3*Math.sin(lt*8),2)))});
    if(k==='spirillum'||k==='spirochete'){const p=el('path',{fill:'none',stroke:dark(C),'stroke-width':k==='spirillum'?26:12,'stroke-linecap':'round'},G),p2=el('path',{fill:'none',stroke:C,'stroke-width':k==='spirillum'?20:8,'stroke-linecap':'round'},G);
      up.push(lt=>{let d='';const n=k==='spirillum'?3:7;for(let u=0;u<=1;u+=.01)d+=(d?' L':'M')+f2(x-170+u*340)+','+f2(y+Math.sin(u*n*TAU-lt*4)*(k==='spirillum'?40:22));p.setAttribute('d',d);p2.setAttribute('d',d)})}});
