/* ---------- BINARY FISSION ---------- */
SM.items.fission=preset(1400,760,(g,it)=>{const TT=it.cycle||10,cx=700,cy=360,A={};const wall=el('path',{fill:vol('#AED581',{hi:.3}),stroke:'#558B2F','stroke-width':8},g);const d1=el('path',{fill:'none',stroke:NAT.dnaC,'stroke-width':6},g),d2=el('path',{fill:'none',stroke:'#E53935','stroke-width':6},g);
  const ribs=[...Array(40)].map((_,i)=>el('circle',{r:5,fill:'#33691E',opacity:.6},g));const cap=txt(g,'',700,700,{size:30,color:'a2'});Object.assign(A,{wall:{el:wall,fx:.3,fy:0},circDNA:d1,septum:()=>[cx,cy+40],ribosomes:ribs[3]});let PIN=0;
  const N=[{uz:'1. Bakteriya o‘sadi',en:'1. The cell grows'},{uz:'2. Halqasimon DNK nusxalanadi',en:'2. Circular DNA is copied'},{uz:'3. Hujayra cho‘ziladi, DNKlar ajraladi',en:'3. Cell elongates, DNA copies separate'},{uz:'4. O‘rtada to‘siq hosil bo‘ladi',en:'4. A septum forms in the middle'},{uz:'5. Ikki bir xil qiz hujayra',en:'5. Two identical daughter cells'}];
  const loop=(x,y,r)=>{let d='';for(let a=0;a<=TAU+.01;a+=.15)d+=(d?' L':'M')+f2(x+Math.cos(a)*r*(1+.15*Math.sin(a*5)))+','+f2(y+Math.sin(a)*r*.6*(1+.15*Math.cos(a*4)));return d};
  return {anchors:A,show:{septum:()=>clamp(PIN*3)},update(lt,p,st){const u=cyc(lt,st,TT,.3);const s=Math.min(4,Math.floor(u/.2)),q=(u%.2)/.2;const el2=s<2?0:s===2?E.inOutCubic(q):1,pinch=s<3?0:s===3?E.inOutCubic(q):1,split=s===4?E.outCubic(q):0;
    PIN=pinch;const L=260+el2*160+split*60,H=130*(1+(s===0?q*.1:.1));// capsule outline pinching at centre
    let d='';const n=80;for(let i=0;i<=n;i++){const a=i/n*TAU;const x=Math.cos(a)*L,ys=Math.sin(a);const pin=1-pinch*Math.exp(-((x/(60+L*.1))**2))*.98;d+=(i?' L':'M')+f2(cx+x+Math.sign(x)*split*40)+','+f2(cy+ys*H*pin)}wall.setAttribute('d',d+'Z');
    const rep=s<1?0:s===1?q:1;const sep=el2*.5+pinch*.5;d1.setAttribute('d',loop(cx-sep*220-split*40,cy,90));d2.setAttribute('d',rep>0?loop(cx+sep*220+split*40+(1-rep)*0,cy,90*clamp(rep*1.2)):'');d2.setAttribute('opacity',f2(clamp(rep*2)));
    ribs.forEach((r,i)=>{const x=cx+(seeded(i,1)-.5)*2*(L-30),y=cy+(seeded(i,2)-.5)*1.6*H*.8;at(r,{cx:f2(x+Math.sign(x-cx)*split*40),cy:f2(y)})});cap.textContent=T(N[s])}}});
