  const seg=(x1,y1,x2,y2,w,c)=>{el('line',{x1,y1,x2,y2,stroke:dark(c,.3),'stroke-width':w+6,'stroke-linecap':'round'},Y);el('line',{x1,y1,x2,y2,stroke:c,'stroke-width':w,'stroke-linecap':'round'},Y)};
