  [[cx-22,600,cx+22,600],[cx-22,560,cx+22,560]].forEach(([a,b,c,d])=>el('line',{x1:a,y1:b,x2:c,y2:d,stroke:'#FDD835','stroke-width':6,'stroke-dasharray':'6 4'},Y));[-1,1].forEach(s=>el('line',{x1:cx+s*110,y1:395,x2:cx+s*150,y2:420,stroke:'#FDD835','stroke-width':6,'stroke-dasharray':'6 4'},Y));
  const ag=[-1,1].map(s=>{const a=el('g',{},g);el('path',{d:blob(0,0,46,40,{seed:s+3,amp:.2,n:10}),fill:vol('#EF5350'),stroke:'#B71C1C','stroke-width':3},a);return {a,s}});
  Object.assign(A,{heavy:[cx-22,700],light:[cx+180,380],variable:[cx+260,160],constant:[cx+22,650],disulfide:[cx,580],hinge:[cx-60,480],fab:[cx-200,330],fc:[cx+40,760],antigen:[cx+300,90]});
