    const S=Math.min(1,W/280);const glow=(rr,c)=>{el('circle',{cx:x,cy:y,r:rr*1.6,fill:c,opacity:.35,filter:'url(#blur24)'},pg);el('circle',{cx:x,cy:y,r:rr,fill:vol(c,{hi:.5,lo:.2})},pg)};
