  const R=300,cx=520,cy=480;const L=el('g',{},g);const ed=edges.map(()=>el('line',{stroke:'#90A4AE','stroke-width':2.5,opacity:.8},L));const sc=it.real?1:.45;
  const balls=cell.map(p=>el('circle',{fill:p[3]?'#43A047':(k==='nacl'?'#7E57C2':'#FFB74D'),stroke:'#0B1220','stroke-width':1.5},L));
