    k==='standing'?[U(`n = ${f1}-moda: L = n·λ/2`,`Mode n = ${f1}: L = n·λ/2`),U(`Tugunlar: ${f1+1}, do‘ngliklar: ${f1}`,`Nodes: ${f1+1}, antinodes: ${f1}`),U('fₙ = n·v/(2L) — tor, quvur','fₙ = n·v/(2L) — strings, pipes')]:[U(`y = ${a1}·sin(2π·${f1}x) + ${a2}·sin(2π·${f2_}x + ${ph})`,`y = ${a1}·sin(2π·${f1}x) + ${a2}·sin(2π·${f2_}x + ${ph})`),U('Superpozitsiya: siljishlar algebraik qo‘shiladi','Superposition: displacements add algebraically')];
