    lines(g,1330,560,[U('Birlamchi javob: 7–14 kun, asosan IgM','Primary response: 7–14 days, mainly IgM'),U('Sinf almashinuvi (AID): IgM → IgG/IgA/IgE','Class switching (AID): IgM → IgG/IgA/IgE'),U('Somatik gipermutatsiya → affinitet yetilishi','Somatic hypermutation → affinity maturation'),U('IgG yarim umri ~21 kun','IgG half-life ~21 days')],{size:17,dy:30});
    Object.assign(A,{l_b:[bx-60,by+60],l_ag:()=>{const t=ag[0].getAttribute('transform')||'';const m=/translate\(([-\d.]+) ([-\d.]+)/.exec(t);return m?[+m[1],+m[2]]:[bx,by-150]},l_tfh:()=>[560+TP[0],230+TP[1]],l_plasma:[1180,245],l_mem:[1180,690],l_ab:[1330,320]});
