  const p=Math.min(1,R0/24);const day=Array(nC*nR).fill(-1);day[idx]=0;let fr=[idx];for(let d=1;d<40&&fr.length;d++){const nx=[];fr.forEach(i=>{const r=Math.floor(i/nC),c=i%nC;for(let dr=-2;dr<=2;dr++)for(let dc=-2;dc<=2;dc++){if(!dr&&!dc)continue;const rr=r+dr,cc=c+dc;if(rr<0||cc<0||rr>=nR||cc>=nC)continue;const j=rr*nC+cc;if(vac[j]||day[j]>=0)continue;if(rnd()<p){day[j]=d;nx.push(j)}}});fr=nx}
