  let info=[];if(k==='partial'){curve(c=>E0(c,100*ea,EC*.5),'#FFCA28',4);info=[U(`Qisman agonist: ichki faollik ${ea} → Emax ${Math.round(ea*100)}%`,`Partial agonist: intrinsic activity ${ea} → Emax ${Math.round(ea*100)}%`),U('To‘liq agonist bilan birga — raqobatli antagonistdek ta’sir qiladi','With a full agonist it behaves like an antagonist'),U('Misol: buprenorfin (μ-opioid), vareniklin (α4β2)','e.g. buprenorphine (μ-opioid), varenicline (α4β2)')]}
  if(k==='competitive'){const r=1+B/KB;curve(c=>E0(c,100,EC*r),'#EF5350',4);arw(g,[ax.px(Math.log10(EC))+6,ax.py(50)],[ax.px(Math.log10(EC*r))-6,ax.py(50)],'#FFFFFF',3);
    info=[U(`[B] = ${B} nM, KB = ${KB} nM → doza nisbati r = 1 + [B]/KB = ${f2(r)}`,`[B] = ${B} nM, KB = ${KB} nM → dose ratio r = 1 + [B]/KB = ${f2(r)}`),U(`Schild: log(r − 1) = log[B] − log KB → pA₂ = ${f2(-Math.log10(KB*1e-9))}`,`Schild: log(r − 1) = log[B] − log KB → pA₂ = ${f2(-Math.log10(KB*1e-9))}`),U('Agonist dozasini oshirib yengib o‘tish mumkin','Surmountable by more agonist'),U('Misol: nalokson (μ), propranolol (β), atropin (M)','e.g. naloxone (μ), propranolol (β), atropine (M)')];A.g_shift=[ax.px(Math.log10(EC*Math.sqrt(r))),ax.py(50)]}
