  const qv=el('text',{x:bx,y:150,'font-size':24,'font-weight':900,fill:TH.ink},g);
  lines(g,bx-20,680,[U(`Misol: kistoz fibroz ~1/${inc} → q = 1/√${inc} = ${q0.toFixed(3)}`,`Example: cystic fibrosis ~1/${inc} → q = 1/√${inc} = ${q0.toFixed(3)}`),U(`Tashuvchilar 2pq = ${(c0*100).toFixed(1)}% ≈ 1/${Math.round(1/c0)}`,`Carriers 2pq = ${(c0*100).toFixed(1)}% ≈ 1/${Math.round(1/c0)}`),U('Shartlar: katta populyatsiya, tasodifiy juftlashish, mutatsiya/migratsiya/tanlanish yo‘q','Assumptions: large population, random mating, no mutation/migration/selection')],{size:20,dy:34,keep:true});
