  let f=X.map(z=>Math.exp(-z*z/2));const norm=a=>{const s=a.reduce((x,y)=>x+y,0);return a.map(v=>v/s)};f=norm(f);const H=[f];const ker=[...Array(21)].map((_,i)=>Math.exp(-Math.pow((i-10)*.05/.25,2)/2));
  for(let t=0;t<30;t++){let a=f.map((v,i)=>v*w(X[i]));a=norm(a);const b=a.map((_,i)=>{let s=0,ws=0;for(let j=-10;j<=10;j++){const q=i+j;if(q>=0&&q<n){s+=a[q]*ker[j+10];ws+=ker[j+10]}}return s/ws});f=norm(b);H.push(f)}
  const mean=a=>a.reduce((s,v,i)=>s+v*X[i],0);const sd=a=>{const m=mean(a);return Math.sqrt(a.reduce((s,v,i)=>s+v*(X[i]-m)*(X[i]-m),0))};
  const ym=Math.max(...H.flat())*1.15;const ax=axes(g,150,170,1000,560,{x:[-4,4],y:[0,ym],xt:[-4,-2,0,2,4],yt:[],xl:U('belgi qiymati (standart og‘ish birligida)','trait value (SD units)'),yl:U('chastota','frequency')});
  const wm=Math.max(...X.map(w));el('path',{d:pth(z=>[ax.px(z),ax.py(w(z)/wm*ym*.95)],-4,4,160),stroke:'#FFCA28','stroke-width':3,fill:'none','stroke-dasharray':'10 6'},g);
  el('path',{d:pth(i=>[ax.px(X[i]),ax.py(H[0][i])],0,n-1,n-1),stroke:'#90A4AE','stroke-width':3,fill:'none'},g);const cur=el('path',{stroke:'#4FC3F7','stroke-width':5,fill:'#4FC3F7','fill-opacity':.15},g);
  const gt=el('text',{x:1200,y:520,'font-size':26,'font-weight':900,fill:TH.ink},g);const st=el('text',{x:1200,y:560,'font-size':20,'font-weight':700,fill:TH.ink},g);
  const T0={directional:U('Yo‘naltiruvchi tanlanish','Directional selection'),stabilizing:U('Barqarorlashtiruvchi tanlanish','Stabilizing selection'),disruptive:U('Dizruptiv (ajratuvchi) tanlanish','Disruptive selection')}[k];ttl(g,T0,1200,200,{size:26});
  lines(g,1200,250,{directional:[U('Qayin odimchasi (Biston betularia), Manchester:','Peppered moth (Biston betularia), Manchester:'),U('qora shakl 1848 ~1% → 1895 ~98% (sanoat qorayishi)','dark form 1848 ~1% → 1895 ~98% (industrial melanism)'),U('Antibiotik va pestitsidlarga chidamlilik','Antibiotic and pesticide resistance')],stabilizing:[U('Chaqaloq vazni: ~3–4 kg da o‘lim eng kam','Birth weight: mortality lowest at ~3–4 kg'),U('O‘rtacha saqlanadi, xilma-xillik kamayadi','Mean kept, variance reduced')],disruptive:[U('Afrika vyurok qushlari (Pyrenestes): katta va kichik tumshuq','African seedcrackers (Pyrenestes): large and small bills'),U('Ikki cho‘qqi — turlanish boshlanishi mumkin','Two peaks — may start speciation')]}[k],{size:20,dy:34,keep:true});
  leg(g,1200,640,[['#FFCA28',U('moslanuvchanlik w(z)','fitness w(z)')],['#90A4AE',U('0-avlod','generation 0')],['#4FC3F7',U('joriy avlod','current generation')]],{size:19,dy:34});
  let gi=0;Object.assign(A,{se_f:[ax.px(k==='directional'?3:k==='stabilizing'?0:3.2),ax.py(ym*.9)],se_0:[ax.px(-.8),ax.py(H[0][70])],se_n:()=>{const a=H[gi];const i=a.indexOf(Math.max(...a));return [ax.px(X[i]),ax.py(a[i])]},se_m:()=>[ax.px(mean(H[gi])),ax.py(0)],se_ex:[1300,260]});
