  const N={at:[850,140,U('Atmosfera N₂','Atmospheric N₂'),'#90A4AE'],nh:[300,450,'NH₄⁺','#81C784'],no2:[850,740,'NO₂⁻','#FFB74D'],no3:[1400,450,'NO₃⁻','#FFCA28'],pl:[850,450,U('O‘simlik va hayvon oqsillari','Plant & animal proteins'),'#4DB6AC']};const B={};Object.entries(N).forEach(([kk,[x,y,l,c]])=>B[kk]=box(g,x,y,kk==='pl'?320:200,70,typeof l==='string'?l:T(l),c,{size:22}));
