const WARN={uz:'Ehtiyot bo‘ling',en:'Caution',ru:'Осторожно'};
const chip=(g,x,y,text,color)=>{const size=24;const w=tw(text,size,700)+64;const b=el('g',{transform:`translate(${f2(x)} ${f2(y)})`},g);
  el('rect',{x:0,y:0,width:w,height:size*1.8,rx:size*.4,fill:color,'fill-opacity':.2,stroke:color,'stroke-width':2.5},b);
  el('path',{d:`M${size*.95},${size*.35} L${size*1.5},${size*1.45} L${size*.4},${size*1.45}Z`,fill:color},b);
  const i=el('text',{x:size*.95,y:size*1.32,'text-anchor':'middle','font-size':size*.7,'font-weight':900,'font-family':FONT,fill:'#111'},b);i.textContent='!';
  const t=el('text',{x:size*1.85,y:size*1.22,'font-size':size,'font-weight':700,'font-family':FONT,fill:color},b);t.textContent=text;return b};
Object.keys(SM.items).forEach(type=>{const B=SM.items[type];if(!B||typeof B.build!=='function'||B._lib)return;const orig=B.build;
  B.build=function(it,ctx){const prevNS=NMSCOPE;NMSCOPE=KIT.NS[type]||null;let R;try{R=orig.call(this,it,ctx)}finally{NMSCOPE=prevNS}if(!R||!R.g||(it.analogy==null&&it.warn==null)||it.analogy===false&&it.warn==null)return R;
    let bx;try{bx=boxOf(it)}catch(e){bx=[60,60,800,600]}const [x,y,w,h]=bx;const g=R.g;
    if(it.analogy&&it.analogy!==false&&type!=='spacetime'){const bd=KIT.badge(g,x+18*SU,y+14*SU,typeof it.analogy==='string'?it.analogy:undefined);bd.setAttribute('data-lib','analogy')}
    if(it.warn){const c=chip(g,x+18*SU,y+h-62*SU,typeof it.warn==='string'?it.warn:(WARN[LANG]||WARN.uz),'#FF7043');c.setAttribute('data-lib','warn')}
    return R};B._lib=1});
